      __webpack_exports__["default"] = "<header class=\"page-header flex-group space-between flex-align-center\">\r\n  <!--LEFT SECTION -->\r\n  <nav>\r\n    <a class=\"flex-align-center app-name\" title=\"Design Language homepage\" routerLink=\"/\" (click)=\"selectedIndex=null\">\r\n      <span\r\n        class=\"\r\n          material-icons\r\n          aa-white-100\r\n          bg-aa-orange-100\r\n          bd-aa-orange-100\r\n          border-orange\r\n          margin-right-0-75\r\n          \"\r\n        >\r\n        design_services\r\n      </span>\r\n      Design Language</a>\r\n  </nav>\r\n\r\n  <!-- MIDDLE SECTION - LOGO -->\r\n  <div class=\"aa-logo\" title=\"Anglo American\"><span>Anglo American</span></div>\r\n\r\n  <!-- MOBILE MENU - HIDDEN FOR DESKTOP -->\r\n  <div class=\"mobile-menu flex-group\">\r\n    <div *ngIf=\"mobileMenu\" class=\"aa-blade-modal\"></div>\r\n    <button (click)=\"toggleTheme()\" class=\"material-icons\">brightness_2</button>\r\n    <button (click)=\"mobileMenu=!mobileMenu\" class=\"material-icons\">menu</button>\r\n  </div>\r\n\r\n\r\n  <!-- RIGHT SECTION NAV-->\r\n  <nav class=\"flex-group flex-end flex-align-center\">\r\n    <ul>\r\n      <!-- search -->\r\n      <li class=\"cursor-pointer\" (click)=\"toggleAppsBlade=false; toggleLoginBlade=false\">\r\n        <div class=\"aa-search\" [ngClass]=\"{'show-search' : showSearch}\">\r\n          <input\r\n            class=\"animate-normal\"\r\n            type=\"text\"\r\n            id=\"search-text\"\r\n            aria-describedby=\"search-text\"\r\n            [(ngModel)]=\"searchText\"\r\n            placeholder=\"Search\"\r\n            autofocus\r\n            >\r\n          <div\r\n            (click)=\"toggleSearchInput(); searchText=''\"\r\n            class=\"material-icons flex-1 cursor-pointer animate-normal\"\r\n          >\r\n            saved_search\r\n          </div>\r\n          <section class=\"search-results\" *ngIf=\"searchText.length && showSearch\">\r\n            <ul>\r\n              <li *ngFor=\"let c of components | appFilter: searchText\" (click)=\"toggleSearchInput()\">\r\n                <a routerLink=\"/{{c}}\" appHighlight [searchedWord]=\"searchText\" [content]=\"c.toString().split('-').join('\\n')\" [classToApply]=\"'highlight'\" [setTitle]=\"'false'\">\r\n                  {{c}}\r\n                </a>\r\n              </li>\r\n            </ul>\r\n          </section>\r\n        </div>\r\n      </li>\r\n      <!-- apps blade -->\r\n      <li class=\"cursor-pointer\" (click)=\"toggleAppsBlade=!toggleAppsBlade; toggleLoginBlade=false; showSearch=false\">\r\n        <div class=\"apps\">\r\n          <div class=\"material-icons\">apps</div>\r\n        </div>\r\n      </li>\r\n\r\n      <!-- login blade -->\r\n      <li class=\"cursor-pointer\" (click)=\"toggleLoginBlade=!toggleLoginBlade; toggleAppsBlade=false; showSearch=false\">\r\n        <div class=\"avatar\">\r\n          <div>\r\n            <img onerror=\"this.style.display='none'\" src=\"./assets/images/samples/obi-wan.png\" />\r\n          </div>\r\n        </div>\r\n      </li>\r\n    </ul>\r\n  </nav>\r\n</header>\r\n\r\n<nav\r\n  class=\"nav-core box-shadow-light nav-container\"\r\n  [ngClass]=\"{ 'minimize-menu' : minimizeMenu, 'show-mobile-menu' : mobileMenu }\"\r\n  >\r\n  <ul>\r\n    <li *ngFor=\"let item of navDataItems; let i = index\">\r\n      <a\r\n        [class.expanded]=\"selectedIndex === i\"\r\n        (click)=\"setIndex(i)\"\r\n        class=\"flex-group flex-align-center flex-start {{item.color}} {{item.customClass}}\"\r\n        [ngClass]=\"{'hide-chevron':!item.nestedItems}\"\r\n      >\r\n        <span class=\"material-icons\">{{item.iconName}}</span>\r\n        <span class=\"margin-right-0-5\">{{item.title}}</span>\r\n      </a>\r\n      <ul [ngStyle]=\"selectedIndex === i && { 'max-height' : item.nestedItems.length * '33' + 'px' }\">\r\n        <li *ngFor=\"let nestedItem of item.nestedItems; let n = index\">\r\n          <a\r\n            (click)=\"setSelectedItem(nestedItem)\"\r\n            [class.selected]=\"nestedItem.isSelected\"\r\n            class=\"flex-group flex-align-center flex-start\"\r\n            routerLink=\"{{nestedItem.routerLink}}\"\r\n            title=\"{{nestedItem.title}}\"\r\n          >\r\n            <span class=\"material-icons {{nestedItem.customClass}}\">{{nestedItem.iconName}}</span>\r\n            <span>{{nestedItem.title}}</span>\r\n          </a>\r\n        </li>\r\n      </ul> \r\n    </li>\r\n  </ul>\r\n  <div class=\"flex-group nav-min-max flex-align-center\">\r\n    <div>{{currentDate | DateFormatPipe }}</div>\r\n    <button (click)=\"minimizeMenu=!minimizeMenu\" class=\"material-icons\">chevron_left</button>\r\n  </div>\r\n</nav>\r\n\r\n<main class=\"main-content\" [ngClass]=\"{'menu-minimized' : minimizeMenu}\">\r\n  <router-outlet></router-outlet>\r\n</main>\r\n\r\n<!-- BLADES -->\r\n<!--toggleAppsBlade-->\r\n<aa-blade\r\n  class=\"apps-blade\"\r\n  [customBlade]=\"true\"\r\n  [showModal]=\"false\"\r\n  [toggleBlade]=\"toggleAppsBlade\"\r\n  suppressAutoClose=\"false\"\r\n  topPosition=\"3.5\"\r\n  zIndex=\"99999\"\r\n  bladeSize=\"one-column-width\"\r\n  bladeHeading=\"Hello\"\r\n  [enableIcon]=\"true\"\r\n  iconName=\"directions_bike\"\r\n  (close)=\"toggleAppsBlade = false\"\r\n  [enablePinning]=\"false\"\r\n>\r\n\r\n  <ng-container custom-header>\r\n    <input\r\n    type=\"text\"\r\n    class=\"search\"\r\n    placeholder=\"Search\"\r\n\r\n    id=\"search-text\"\r\n    aria-describedby=\"search-text\"\r\n    [(ngModel)]=\"searchText\"\r\n    placeholder=\"Filter by App name\"\r\n    autofocus\r\n    />\r\n  </ng-container>\r\n\r\n  <ng-container custom-content>\r\n    <div *ngIf=\"!hideMe\" class=\"describe\">\r\n      Please note that these icons are currently\r\n      mapped to the Font Awesome (fa) classnames\r\n      written in Core Db. We have now added the\r\n      (.icon-app-name) class that correspond to the\r\n      actual App itself. It would be good to\r\n      update these in the Db at some point. <a (click)=\"hideMe=true\">Hide</a>\r\n    </div>\r\n    <section class=\"blade-navigation flex-group\">\r\n\r\n      <div class=\"nav-icon\" *ngFor=\"let i of appIconItems | appIcons: searchText; let f = index\">\r\n        <button\r\n          (click)=\"favClicked(f)\"\r\n          class=\"icon-star-favourites transparent width-3\"\r\n          [class.selected]=\"favIndex === f\">\r\n        </button>\r\n        <a class=\"{{i.appIconClass}}\"></a>\r\n        <p>{{i.appIconName}}</p>\r\n      </div>\r\n\r\n    </section>\r\n  </ng-container>\r\n  <ng-container custom-footer>\r\n    <aa-button\r\n      (buttonClick)=\"toggleAppsBlade=false\"\r\n      buttonText=\"Close\"\r\n      buttonClass=\"cancel\"\r\n      fieldClass=\"label-hidden\">\r\n    </aa-button>\r\n  </ng-container>\r\n\r\n</aa-blade>\r\n\r\n<!--toggleLoginBlade-->\r\n<aa-blade\r\n  class=\"login-blade\"\r\n  [customBlade]=\"false\"\r\n  [showModal]=\"false\"\r\n  [toggleBlade]=\"toggleLoginBlade\"\r\n  suppressAutoClose=\"false\"\r\n  topPosition=\"3.5\"\r\n  zIndex=\"999\"\r\n  bladeSize=\"one-column-width\"\r\n  [enableIcon]=\"true\"\r\n  iconName=\"directions_bike\"\r\n  (close)=\"toggleLoginBlade = false\"\r\n  [enablePinning]=\"false\"\r\n>\r\n\r\n<article class=\"blade-content\">\r\n  <div class=\"flex-group flex-start\">\r\n    <div class=\"avatar\">\r\n      <div>\r\n        <img onerror=\"this.style.display='none'\" src=\"./assets/images/samples/obi-wan.png\" />\r\n      </div>\r\n    </div>\r\n    <div>\r\n      <h2 class=\"margin-bottom-0-25\">Michael King</h2>\r\n      <a class=\"cursor-pointer\" mailto=\"michael.king@angloamerican.com\">michael.king@angloamerican.com</a>\r\n    </div>\r\n  </div>\r\n</article>\r\n<article class=\"blade-footer flex-group space-between\">\r\n  <div class=\"field\">\r\n    <button (click)=\"toggleTheme()\" class=\"transparent anchor-blue padding-0\">\r\n      <div class=\"flex-group ng-star-inserted\">\r\n        Switch to dark mode\r\n      </div>\r\n    </button>\r\n  </div>\r\n  <div class=\"field\">\r\n    <button (click)=\"toggleLoginBlade=false\" class=\"transparent anchor-blue padding-0\">\r\n      Close\r\n    </button>\r\n  </div>\r\n</article>\r\n</aa-blade>";
