      __webpack_exports__["default"] = "<section class=\"control-bar flex-group space-between\">\r\n  <h1>Checkbox</h1>\r\n  <aa-alert alertClass=\"error\" alertText=\"Please ensure all fieldset inputs are wrapped in div.field label\"></aa-alert>\r\n</section>\r\n\r\n<section class=\"content-container padding-0\">\r\n  <!-- start content repeater -->\r\n  <section class=\"content-repeater flex-group\">\r\n    <section class=\"flex-1 col-left flex-start\">\r\n      <h2>Checkbox</h2>\r\n      <div class=\"describe margin-bottom-1\">\r\n        <p>Below is the standard checkbox. If you're using straight HTML markup, Please\r\n          remember to use a div.field.checkout nested inside a fieldset.\r\n        </p>\r\n      </div>\r\n      <fieldset>\r\n        <legend>Checkbox</legend>\r\n        <div class=\"field checkbox boxed\">\r\n          <label for=\"checkboxIdOne\">\r\n            <input \r\n              type=\"checkbox\" \r\n              value=\"disabled\" \r\n              name=\"myCheckbox\"\r\n              id=\"checkboxIdOne\" \r\n              checked=\"checked\">\r\n            <span>Chickens</span>\r\n          </label>\r\n        </div>\r\n        <aa-checkbox \r\n          checkboxChecked=\"'checkboxChecked'\" \r\n          checkboxId=\"checkboxIdTwo\" \r\n          checkboxName=\"myCheckboxes\"\r\n          checkboxText=\"Foxes\" \r\n          checkboxValue=\"Foxes\"\r\n          fieldClass=\"boxed\">\r\n        </aa-checkbox>\r\n        <aa-checkbox \r\n          checkboxChecked=\"checkboxChecked\" \r\n          checkboxId=\"checkboxIdThree\" \r\n          checkboxName=\"myCheckboxes\"\r\n          checkboxText='Cats (disable=\"true\")'\r\n          checkboxValue=\"Disabled\"\r\n          fieldClass=\"boxed\"\r\n          disabled=\"true\">\r\n        </aa-checkbox>\r\n      </fieldset>\r\n      <h2 class=\"margin-top-1\">Adding an additional tooltip</h2>\r\n      <fieldset>\r\n        <div class=\"field checkbox\">\r\n          <label>\r\n            <input type=\"checkbox\"/>\r\n            <span>Adding a tooltip</span>\r\n            <aa-tooltip \r\n              [isInfo]=\"true\" \r\n              [customIcon]=\"true\" \r\n              iconName=\"help\"\r\n              setMinWidth=\"20\" \r\n              ypos=\"bottom\" \r\n              xpos=\"right\"\r\n              zIndex=\"1\"\r\n            >\r\n              <h4>Adding a tooltip</h4>\r\n              <p>If you would like to add an additional tooltip (aa-tooltip) to your\r\n                checkbox, please nest the tooltip inside the label element as the last-child\r\n              </p>\r\n          </aa-tooltip>\r\n        </label>\r\n        </div>\r\n      </fieldset>\r\n    </section>\r\n      \r\n    <section class=\"flex-2 col-right flex-start\">\r\n      <table class=\"half-width\">\r\n        <caption>Attributes</caption>\r\n        <thead>\r\n          <tr>\r\n            <th>Element</th>\r\n            <th>Attribute</th>\r\n            <th>Type</th>\r\n            <th>Default</th>\r\n          </tr>\r\n        </thead>\r\n        <tbody>\r\n          <tr>\r\n            <td datalabel=\"Element\">Fieldset</td>\r\n            <td datalabel=\"Attribute\">N/A</td>\r\n            <td datalabel=\"Type\">Fieldset</td>\r\n            <td datalabel=\"Default\">N/A</td>\r\n          </tr>\r\n          <tr>\r\n            <td datalabel=\"Element\">Input</td>\r\n            <td datalabel=\"Attribute\">checkboxChecked</td>\r\n            <td datalabel=\"Type\">Checkbox</td>\r\n            <td datalabel=\"Default\">checked</td>\r\n          </tr>\r\n          <tr>\r\n            <td datalabel=\"Element\">Input</td>\r\n            <td datalabel=\"Attribute\">checkboxId</td>\r\n            <td datalabel=\"Type\">Id</td>\r\n            <td datalabel=\"Default\">myCheckboxId</td>\r\n          </tr>\r\n          <tr>\r\n            <td datalabel=\"Element\">Input</td>\r\n            <td datalabel=\"Attribute\">checkboxName</td>\r\n            <td datalabel=\"Type\">Name</td>\r\n            <td datalabel=\"Default\">myCheckboxName</td>\r\n          </tr>\r\n          <tr>\r\n            <td datalabel=\"Element\">Input</td>\r\n            <td datalabel=\"Attribute\">checkboxValue</td>\r\n            <td datalabel=\"Type\">Value</td>\r\n            <td datalabel=\"Default\">myCheckboxValue</td>\r\n          </tr>\r\n          <tr>\r\n            <td datalabel=\"Element\">Input</td>\r\n            <td datalabel=\"Attribute\">disabled</td>\r\n            <td datalabel=\"Type\">N/A</td>\r\n            <td datalabel=\"Default\">false</td>\r\n          </tr>\r\n          <tr>\r\n            <td datalabel=\"Element\">Span</td>\r\n            <td datalabel=\"Attribute\">checkboxText</td>\r\n            <td datalabel=\"Type\">Text</td>\r\n            <td datalabel=\"Default\">Chickens</td>\r\n          </tr>\r\n          <tr>\r\n            <td colspan=\"4\">\r\n              <h3>Adding an additional tooltip</h3>\r\n            </td>\r\n          </tr>\r\n          <tr>\r\n            <td datalabel=\"Element\">Label > aa-tooltip (Nested as last-child)</td>\r\n            <td datalabel=\"Attribute\">Component</td>\r\n            <td datalabel=\"Type\">Component</td>\r\n            <td datalabel=\"Default\">N/A</td>\r\n          </tr>\r\n        </tbody>\r\n      </table>\r\n    </section>\r\n    \r\n    <!-- mini menu -->\r\n    <nav class=\"mini-menu flex-group flex-end\">\r\n        <button class=\"custom-icons bg-aa-light-blue-100\" (click)=\"bladeIsOpen($event); showCheckbox=true; showCheckboxFeature=false\">\r\n          <span class=\"material-icons\">visibility</span><span>View gist</span>\r\n        </button>\r\n      </nav>\r\n  </section>\r\n  \r\n  <!-- start content repeater -->\r\n  <section class=\"content-repeater flex-group\">\r\n    <section class=\"flex-1 col-left flex-start\">\r\n      <h2>Checkbox feature</h2>\r\n      <div class=\"describe margin-bottom-1\">\r\n        <p>If you want your checkboxes to stand out, wrap a <strong>section.feature-box.solid</strong> around\r\n          the fieldset. <strong>For validation, add the class .error to the nested div.field.error</strong>.\r\n        </p>\r\n      </div>\r\n      <section class=\"feature-box solid max-readable-width\">\r\n        <fieldset class=\"boxed\">\r\n          <legend>Checkbox</legend>\r\n          <div class=\"field checkbox boxed\">\r\n            <label for=\"checkboxIdFour\">\r\n              <input \r\n                type=\"checkbox\" \r\n                value=\"disabled\" \r\n                name=\"myCheckbox\"\r\n                id=\"checkboxIdFour\" \r\n                checked=\"checked\">\r\n              <span>Chickens</span>\r\n            </label>\r\n          </div>\r\n          <aa-checkbox \r\n            checkboxChecked=\"'checkboxChecked'\" \r\n            checkboxId=\"checkboxIdFive\" \r\n            checkboxName=\"myCheckboxes\"\r\n            checkboxText=\"Foxes\" \r\n            checkboxValue=\"Foxes\"\r\n            fieldClass=\"boxed\">\r\n          </aa-checkbox>\r\n          <aa-checkbox \r\n            checkboxChecked=\"checkboxChecked\" \r\n            checkboxId=\"checkboxIdSix\" \r\n            checkboxName=\"myCheckboxes\"\r\n            checkboxText=\"Disabled\" \r\n            checkboxValue=\"Disabled\"\r\n            fieldClass=\"boxed\"\r\n            disabled=\"true\">\r\n          </aa-checkbox>\r\n        </fieldset>\r\n      </section>\r\n    </section>\r\n      \r\n    <section class=\"flex-2 col-right flex-start\">\r\n      <table class=\"half-width\">\r\n        <caption>Attributes</caption>\r\n        <thead>\r\n          <tr>\r\n            <th>Element</th>\r\n            <th>Attribute</th>\r\n            <th>Type</th>\r\n            <th>Default</th>\r\n          </tr>\r\n        </thead>\r\n        <tbody>\r\n          <tr>\r\n            <td datalabel=\"Element\">Section</td>\r\n            <td datalabel=\"Attribute\">N/A</td>\r\n            <td datalabel=\"Type\">Class</td>\r\n            <td datalabel=\"Default\">.feature-box .solid</td>\r\n          </tr>\r\n        </tbody>\r\n      </table>\r\n    </section>\r\n    \r\n    <!-- mini menu -->\r\n    <nav class=\"mini-menu flex-group flex-end\">\r\n        <button class=\"custom-icons bg-aa-light-blue-100\" (click)=\"bladeIsOpen($event); showCheckbox=false; showCheckboxFeature=true\">\r\n          <span class=\"material-icons\">visibility</span><span>View gist</span>\r\n        </button>\r\n      </nav>\r\n  </section>\r\n</section>\r\n\r\n<aa-blade \r\n    [showModal]=\"false\"\r\n    [toggleBlade]=\"toggleBlade\"\r\n    suppressAutoClose=\"false\"\r\n    topPosition=\"3.5\"\r\n    zIndex=\"2\"\r\n    bladeSize=\"one-column-width\"\r\n    bladeHeading=\"Gist\"\r\n    [enableIcon]=\"true\"\r\n    iconName=\"table_rows\"\r\n    (close)=\"toggleBlade = false\"\r\n  >\r\n  <article class=\"blade-content\">\r\n    <div *ngIf=\"showCheckbox\">\r\n      <a href=\"https://gist.github.com/angloux/949a17edd98577d82e9f6239836ad5df\" target=\"_blank\">View Gist on GitHub</a>\r\n      <app-gist src=\"angloux/949a17edd98577d82e9f6239836ad5df\"></app-gist>\r\n    </div>\r\n    <div *ngIf=\"showCheckboxFeature\">\r\n      <a href=\"https://gist.github.com/angloux/28c0038bfdf948e34d0912c72c7ab508\" target=\"_blank\">View Gist on GitHub</a>\r\n      <app-gist src=\"angloux/28c0038bfdf948e34d0912c72c7ab508\"></app-gist>\r\n    </div>\r\n  </article>\r\n</aa-blade>";
