      __webpack_exports__["default"] = "<section class=\"control-bar flex-group space-between\">\r\n  <h1>Input</h1>\r\n  <aa-alert alertClass=\"error\" alertText=\"Please ensure ALL elements are wrapped in div.field\"></aa-alert>\r\n</section>\r\n\r\n<section class=\"content-container padding-0\">\r\n  <!-- start content repeater -->\r\n  <section class=\"content-repeater flex-group\">\r\n    <section class=\"flex-1 col-left flex-start\">\r\n      <h2>Text input</h2>\r\n      <div class=\"describe margin-bottom-1\">\r\n        <p>All inputs should be wrapped inside a div.field, please refer to <a routerLink=\"/field\">Field - input wrapper</a> section. \r\n          All form element inputs are mandatory unless marked as optional. If an input is optional, please set [isOptional]=\"true\".</p>\r\n      </div>\r\n      <div class=\"flex-group\">\r\n        <aa-input-text \r\n          inputTextId=\"input-text-01\"\r\n          inputValue=\"\"\r\n          inputTextLabel=\"Input text\"\r\n          fieldClass=\"\" \r\n          inputPlaceholder=\"Text\">\r\n        </aa-input-text>\r\n    \r\n        <aa-input-text \r\n          inputTextId=\"input-text-01\"\r\n          inputValue=\"\"\r\n          inputTextLabel=\"Input text small\"\r\n          fieldClass=\"small\" \r\n          inputPlaceholder=\"Text small\">\r\n        </aa-input-text>\r\n      </div>\r\n      <div class=\"flex-group\">\r\n        <div class=\"field optional\">\r\n          <label for=\"text-input-1\">Field optional</label>\r\n          <input type=\"text\" name=\"text-input-1\" id=\"text-input-1\" placeholder=\"Field\" />\r\n        </div>     \r\n      </div>\r\n      <div class=\"flex-group\"> \r\n        <aa-input-text \r\n          [readOnly]=\"true\"\r\n          inputTextId=\"input-text-03\"\r\n          inputValue=\"\"\r\n          inputTextLabel=\"Readonly\"\r\n          fieldClass=\"small\" \r\n          inputPlaceholder=\"Can tab to, focus and copy\">\r\n        </aa-input-text>\r\n        <div class=\"field\">\r\n          <label>Disabled</label>\r\n          <input type=\"text\" placeholder=\"Can't tab to, or copy\" disabled=\"disabled\">\r\n        </div>\r\n      </div>\r\n      <div class=\"field\">\r\n        <label for=\"text-input-1\">Confirmation dialog</label>\r\n        <input type=\"text\" placeholder=\"Test\" />\r\n        <article class=\"confirmation flex-group\">\r\n          <div class=\"flex-group flex-start flex-2\">\r\n            <div class=\"material-icons flex-1\">error_outline</div>\r\n            <p class=\"small flex-4\">\r\n              This field must be completed in English. Would you also<br/>\r\n              like to enter this information in your native language?\r\n            </p>\r\n          </div>\r\n          <div class=\"flex-group flex-end flex-1\">\r\n            <div class=\"field radio small\">\r\n              <label [ngClass]=\"{'checked': myRadios==='yes'}\">\r\n                <input [(ngModel)]=\"myRadios\" name=\"myRadios\" type=\"radio\" value=\"yes\">\r\n                <span>Yes</span>\r\n              </label>\r\n            </div>\r\n            <div class=\"field radio small\">\r\n              <label [ngClass]=\"{'checked': myRadios==='no'}\">\r\n                <input [(ngModel)]=\"myRadios\" name=\"myRadios\" type=\"radio\" value=\"no\">\r\n                <span>No</span>\r\n              </label>\r\n            </div>\r\n          </div>\r\n        </article>\r\n      </div>\r\n    </section>\r\n      \r\n    <section class=\"flex-2 col-right flex-start\">\r\n      <table class=\"half-width\">\r\n        <caption>Attributes</caption>\r\n        <thead>\r\n          <tr>\r\n            <th>Element</th>\r\n            <th>Attribute</th>\r\n            <th>Type</th>\r\n            <th>Default</th>\r\n          </tr>\r\n        </thead>\r\n        <tbody>\r\n          <tr>\r\n            <td datalabel=\"Element\">Input</td>\r\n            <td datalabel=\"Attribute\">inputValue</td>\r\n            <td datalabel=\"Type\">Value</td>\r\n            <td datalabel=\"Default\">Your value</td>\r\n          </tr>\r\n          <tr>\r\n            <td datalabel=\"Element\">Input</td>\r\n            <td datalabel=\"Attribute\">inputTextId</td>\r\n            <td datalabel=\"Type\">Id</td>\r\n            <td datalabel=\"Default\">Your Id</td>\r\n          </tr>\r\n          <tr>\r\n            <td datalabel=\"Element\">Input</td>\r\n            <td datalabel=\"Attribute\">inputTextLabel</td>\r\n            <td datalabel=\"Type\">Any</td>\r\n            <td datalabel=\"Default\">Your label</td>\r\n          </tr>\r\n          <tr>\r\n            <td datalabel=\"Element\">Input</td>\r\n            <td datalabel=\"Attribute\">inputPlaceholder</td>\r\n            <td datalabel=\"Type\">Any</td>\r\n            <td datalabel=\"Default\">Your placeholder</td>\r\n          </tr>\r\n          <tr>\r\n            <td datalabel=\"Element\">Input</td>\r\n            <td datalabel=\"Attribute\">[isOptional]</td>\r\n            <td datalabel=\"Type\">Boolean</td>\r\n            <td datalabel=\"Default\">false</td>\r\n          </tr>\r\n          <tr>\r\n            <td datalabel=\"Element\">Input</td>\r\n            <td datalabel=\"Attribute\">[readOnly]</td>\r\n            <td datalabel=\"Type\">Boolean</td>\r\n            <td datalabel=\"Default\">false</td>\r\n          </tr>\r\n          <tr>\r\n            <td datalabel=\"Element\">Input</td>\r\n            <td datalabel=\"Attribute\">fieldClass</td>\r\n            <td datalabel=\"Type\">Class</td>\r\n            <td datalabel=\"Default\">.boxed</td>\r\n          </tr>\r\n        </tbody>\r\n      </table>\r\n    </section>\r\n    \r\n    <!-- mini menu -->\r\n    <nav class=\"mini-menu flex-group flex-end\">\r\n        <button class=\"custom-icons bg-aa-light-blue-100\" (click)=\"bladeIsOpen($event); showInput=true; showInputSmall=false; showTwoCol=false; showDate=false\">\r\n          <span class=\"material-icons\">visibility</span><span>View gist</span>\r\n        </button>\r\n      </nav>\r\n  </section>\r\n  \r\n   <!-- start content repeater -->\r\n   <section class=\"content-repeater flex-group\">\r\n    <section class=\"flex-1 col-left flex-start\">\r\n      <h2>Child text input</h2>\r\n      <div class=\"describe margin-bottom-1\">\r\n        <p>To display a child field element use div.field.child, please refer to<br/>\r\n          <a routerLink=\"/field\">Field section</a></p>\r\n      </div>\r\n        <aa-input-text \r\n          inputTextId=\"input-text-01\" \r\n          inputValue = \"\"\r\n          inputTextLabel=\"Input text\" \r\n          fieldClass=\"child\"\r\n          inputPlaceholder=\"Child\">\r\n        </aa-input-text>\r\n    </section>\r\n      \r\n    <section class=\"flex-2 col-right flex-start\">\r\n      <table class=\"half-width\">\r\n        <caption>Attributes</caption>\r\n        <thead>\r\n          <tr>\r\n            <th>Element</th>\r\n            <th>Attribute</th>\r\n            <th>Type</th>\r\n            <th>Default</th>\r\n          </tr>\r\n        </thead>\r\n        <tbody>\r\n          <tr>\r\n            <td datalabel=\"Element\">Input</td>\r\n            <td datalabel=\"Attribute\">fieldClass</td>\r\n            <td datalabel=\"Type\">Class</td>\r\n            <td datalabel=\"Default\">.child</td>\r\n          </tr>\r\n        </tbody>\r\n      </table>\r\n    </section>\r\n    \r\n    <!-- mini menu -->\r\n    <nav class=\"mini-menu flex-group flex-end\">\r\n        <button class=\"custom-icons bg-aa-light-blue-100\" (click)=\"bladeIsOpen($event); showInput=false; showInputSmall=true; showTwoCol=false; showDate=false\">\r\n          <span class=\"material-icons\">visibility</span><span>View gist</span>\r\n        </button>\r\n      </nav>\r\n  </section>\r\n  \r\n  <!-- start content repeater -->\r\n  <section class=\"content-repeater flex-group\">\r\n    <section class=\"flex-1 col-left flex-start\">\r\n      <h2>2-col layout</h2>\r\n      <div class=\"describe margin-bottom-1\">\r\n        <p>There are a few ways to achieve a two column layout use flex, but we have added\r\n          a simple approach which can be seen below.\r\n        </p>\r\n      </div>\r\n      <article class=\"max-width-50\">\r\n        <div class=\"flex-group\">\r\n          <aa-input-text [inputTextId]=\"'input-text-03'\" [inputTextLabel]=\"'Input text'\"></aa-input-text>\r\n          <aa-input-text [inputTextId]=\"'input-text-04'\" [inputTextLabel]=\"'Input text'\"></aa-input-text>\r\n          <div class=\"flex-align-end\"><a class=\"anchor-blue anchor-underline padding-bottom-0-5\">Remove</a></div>\r\n        </div>\r\n        <div class=\"flex-group\">\r\n          <aa-input-text [inputTextId]=\"'input-text-05'\" [inputTextLabel]=\"'Input text'\"></aa-input-text>\r\n          <aa-input-text [inputTextId]=\"'input-text-06'\" [inputTextLabel]=\"'Input text'\"></aa-input-text>\r\n          <div class=\"flex-align-end\"><a class=\"anchor-blue anchor-underline padding-bottom-0-5\">Remove</a></div>\r\n        </div>\r\n      </article>\r\n    </section>\r\n      \r\n    <section class=\"flex-2 col-right flex-start\">\r\n      <table class=\"half-width\">\r\n        <caption>Attributes</caption>\r\n        <thead>\r\n          <tr>\r\n            <th>Element</th>\r\n            <th>Attribute</th>\r\n            <th>Type</th>\r\n            <th>Default</th>\r\n          </tr>\r\n        </thead>\r\n        <tbody>\r\n          <tr>\r\n            <td datalabel=\"Element\">Article</td>\r\n            <td datalabel=\"Attribute\">Class</td>\r\n            <td datalabel=\"Type\">Class</td>\r\n            <td datalabel=\"Default\">.max-width-50</td>\r\n          </tr>\r\n        </tbody>\r\n      </table>\r\n    </section>\r\n    \r\n    <!-- mini menu -->\r\n    <nav class=\"mini-menu flex-group flex-end\">\r\n        <button class=\"custom-icons bg-aa-light-blue-100\" (click)=\"bladeIsOpen($event); showInput=false; showInputSmall=false; showTwoCol=true; showDate=false\">\r\n          <span class=\"material-icons\">visibility</span><span>View gist</span>\r\n        </button>\r\n      </nav>\r\n  </section>\r\n  <!-- start content repeater -->\r\n  <section class=\"content-repeater flex-group\">\r\n    <section class=\"flex-1 col-left flex-start\">\r\n      <h2>Date-picker</h2>\r\n      <div class=\"describe margin-bottom-1\">\r\n        <p>For date-pickers, use the \r\n          <a href=\"https://ng-bootstrap.github.io/#/components/datepicker/examples\" target=\"_blank\">NGB datepicker</a> \r\n          along with our markup which is styled specifically to match our branding. <strong class=\"aa-red-100\">The date-picker placeholder\r\n            format should be dd-mon-yyyy and the rendered date format that then appears in the UI should be unhyphenated and capitalized, for\r\n            example 01 Jan 2021\r\n          </strong></p>\r\n      </div>\r\n      <div class=\"flex-group\">\r\n        <div class=\"field\">\r\n          <label for=\"text-input-2\">Date</label>\r\n          <div class=\"date-picker\">\r\n            <input type=\"text\" name=\"text-input-2\" id=\"text-input-2\" placeholder=\"dd-mon-yyyy\" />\r\n            <button class=\"material-icons\">date_range</button>\r\n          </div>\r\n        </div>\r\n        \r\n        <div class=\"field\">\r\n          <label for=\"text-input-2\">Date readonly</label>\r\n          <div class=\"date-picker\">\r\n            <input type=\"text\" name=\"text-input-2\" id=\"text-input-2\" placeholder=\"dd-mon-yyyy\" readonly />\r\n            <button class=\"material-icons\">date_range</button>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </section>\r\n      \r\n    <section class=\"flex-2 col-right flex-start\">\r\n      <table class=\"half-width\">\r\n        <caption>Attributes</caption>\r\n        <thead>\r\n          <tr>\r\n            <th>Element</th>\r\n            <th>Attribute</th>\r\n            <th>Type</th>\r\n            <th>Default</th>\r\n          </tr>\r\n        </thead>\r\n        <tbody>\r\n          <tr>\r\n            <td datalabel=\"Element\">Div</td>\r\n            <td datalabel=\"Attribute\">.field</td>\r\n            <td datalabel=\"Type\">Class</td>\r\n            <td datalabel=\"Default\">.field</td>\r\n          </tr>\r\n          <tr>\r\n            <td datalabel=\"Element\">Child div</td>\r\n            <td datalabel=\"Attribute\">.date-picker</td>\r\n            <td datalabel=\"Type\">Class</td>\r\n            <td datalabel=\"Default\">.date-picker</td>\r\n          </tr>\r\n          <tr>\r\n            <td datalabel=\"Element\">Child div button</td>\r\n            <td datalabel=\"Attribute\">.material-icons</td>\r\n            <td datalabel=\"Type\">String</td>\r\n            <td datalabel=\"Default\">date_range</td>\r\n          </tr>\r\n        </tbody>\r\n      </table>\r\n    </section>\r\n    \r\n    <!-- mini menu -->\r\n    <nav class=\"mini-menu flex-group flex-end\">\r\n        <button class=\"custom-icons bg-aa-light-blue-100\" (click)=\"bladeIsOpen($event); showInput=false; showInputSmall=false; showTwoCol=false; showDate=true\">\r\n          <span class=\"material-icons\">visibility</span><span>View gist</span>\r\n        </button>\r\n      </nav>\r\n  </section>\r\n</section>\r\n\r\n<aa-blade \r\n    [showModal]=\"false\"\r\n    [toggleBlade]=\"toggleBlade\"\r\n    suppressAutoClose=\"false\"\r\n    topPosition=\"3.5\"\r\n    zIndex=\"2\"\r\n    bladeSize=\"one-column-width\"\r\n    bladeHeading=\"Gist\"\r\n    [enableIcon]=\"true\"\r\n    iconName=\"table_rows\"\r\n    (close)=\"toggleBlade = false\"\r\n  >\r\n  <article class=\"blade-content\">\r\n    <div *ngIf=\"showInput\">\r\n      <app-gist src=\"angloux/586c1c2fed174b58de0da7a45e922ada\"></app-gist>\r\n      <a href=\"https://gist.github.com/angloux/586c1c2fed174b58de0da7a45e922ada\" target=\"_blank\">View Gist on GitHub</a>\r\n    </div>\r\n    <div *ngIf=\"showInputSmall\">\r\n      <app-gist src=\"angloux/e553f62051539dcef6ec6fd75dfd6b26\"></app-gist>\r\n      <a href=\"https://gist.github.com/angloux/e553f62051539dcef6ec6fd75dfd6b26\" target=\"_blank\">View Gist on GitHub</a>\r\n    </div>\r\n    <div *ngIf=\"showTwoCol\">\r\n      <app-gist src=\"angloux/bfb3a92e9b04361507bb0a31ca476b48\"></app-gist>\r\n      <a href=\"https://gist.github.com/angloux/bfb3a92e9b04361507bb0a31ca476b48\" target=\"_blank\">View Gist on GitHub</a>\r\n    </div>\r\n    <div *ngIf=\"showDate\">\r\n      <app-gist src=\"angloux/c137711141d9d093475458e9dbc16709\"></app-gist>\r\n      <a href=\"https://gist.github.com/angloux/c137711141d9d093475458e9dbc16709\" target=\"_blank\">View Gist on GitHub</a>\r\n    </div> \r\n  </article>\r\n</aa-blade>\r\n";
